def valid(menu, votes):
    if not isinstance(menu, list) or not isinstance(votes, list):
        return False
    if not (2 <= len(menu) <= 10) or not (3 <= len(votes) <= 1000):
        return False
    for s in menu + votes:
        if not isinstance(s, str) or not (1 <= len(s) <= 50):
            return False
        if not (s.isascii() and s.isalpha()):
            return False
    if len(set(menu)) != len(menu):
        return False
    if any(v not in menu for v in votes):
        return False
    counts = [votes.count(m) for m in menu]
    return counts.count(max(counts)) == 1

